var bus = new Solution.EventBus();
var log = new List<string>();
bus.Subscribe(m => log.Add("a:" + m));
bus.Subscribe(m => log.Add("b:" + m));
bus.Publish("go");
Cj.Eq(string.Join("|", log), "a:go|b:go", "both subscribers, in order");

var bus = new Solution.EventBus();
var log = new List<string>();
Action<string> h = m => log.Add("h:" + m);
bus.Subscribe(h);
bus.Unsubscribe(h);
bus.Publish("x");
Cj.Eq(log.Count, 0, "unsubscribed handler does not fire");
bus.Publish("y");
Cj.Eq(log.Count, 0, "still silent — and no crash with zero subscribers");
